import {mountTrailer,stopTrailer} from './trailer.js';
import {DECISION_RESEARCH} from './research.js';
import {AI_PRIMER,AI_CONTEXT,LAW_CONTEXT,POLICY_LENSES} from './context.js';
import {mountExplainer,stopExplainer} from './explainer.js';
import {narrationMarkup,mountNarration,stopNarration} from './narration.js';
import EXPLAINER_MANIFEST from '../assets/explainers/manifest.json';
import {CHAPTERS,CHARACTERS,DISTRICTS,EVENTS,PROJECTS,POLICIES,METRICS,SOURCES,MODEL_CARDS,EFFECT_NOTES} from './data.js';
import * as G from './engine.js';
import {World} from './world.js';
import {AudioDirector} from './audio.js';
import {SCENES,ARCS,storyAfter} from './story.js';
import {PORTRAITS,CLIPS,SCENE_IMAGES,CINEMA,EXPLAINER_MEDIA,TRAILER} from './media.js';
import {outcomeStory,cinematicStory,imageAlt} from './visual-story.js';
import {filmMarkup,mountFilms,stopFilms} from './cinema.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='talos-civic-mandate-v1';let state=null,selectedChoice=-1,tab='map',modal=null,selectedAdvisor='mara',world=null,lastSaved=false,tutorial=false,toastTimer,prologueStep=0,prologueActive=false;
const audio=new AudioDirector();const app=$('#app'),modalRoot=$('#modal-root');
function portrait(id,cls=''){return `<img class="portrait ${cls}" src="${PORTRAITS[id]}" alt="${CHARACTERS.find(c=>c.id===id)?.name||id}" draggable="false">`;}
function button(label,action,cls='',extra=''){return `<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;}
function chip(text,cls=''){return `<span class="chip ${cls}">${text}</span>`;}
function effects(e,compact=false){return Object.entries(e||{}).map(([k,v])=>`<span class="effect ${v>0?'positive':'negative'}" title="${METRICS[k]?.name}">${v>0?'+':''}${Math.round(v*10)/10} ${compact?METRICS[k]?.short:METRICS[k]?.name}</span>`).join('');}
function store(){if(!state)return;try{localStorage.setItem(KEY,G.saveGame(state));lastSaved=true;}catch(e){lastSaved=false;toast('Browser storage is unavailable. Export a save from the menu.');}}
function readSaved(){try{const raw=localStorage.getItem(KEY);return raw?G.loadGame(raw):null;}catch{return null;}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4600);}
function download(name,text,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);}
function render(){
 if(prologueActive){showPrologue();return;}
 document.querySelector('#author-credit').innerHTML='By <a href="https://miguelguerrero.eu" target="_blank" rel="noopener noreferrer">Miguel Guerrero</a>';document.body.classList.toggle('in-game',!!state);document.body.classList.toggle('simple-view',!!state?.settings.simple);document.body.classList.toggle('reduced',!!state?.settings.reducedMotion);
 if(!state){landing();return;}
 world?.setState(state);world?.select(state.selected);if($('.district-select'))$('.district-select').value=state.selected;if(world)world.reduced=state.settings.reducedMotion;
 if(state.settings.simple){renderSimple();return;}
 const ch=CHAPTERS[state.chapter];
 app.innerHTML=`<header class="topbar"><button class="wordmark" data-action="menu" aria-label="Open game menu">TALOS<span>REPUBLIC OF TALOS</span></button><div class="campaign-label">${state.mode==='campaign'?'THREE POSSIBLE FUTURES':'SINGLE SCENARIO'}<strong>${ch.n} / ${ch.title}</strong></div><div class="top-tools">${button(state.settings.sound?'♫ Sound on':'♫ Sound off','sound','quiet')}${button('Help','help','quiet')}${button('Menu','menu','quiet')}</div></header>
 <section class="metrics" aria-label="Republic status">${Object.entries(METRICS).map(([k,m])=>`<div class="metric ${state.stats[k]<30?'danger':''}" title="${m.tip}"><span class="metric-icon" style="color:${m.color}">${m.icon}</span><div><small>${m.short}</small><strong>${Math.round(state.stats[k])}<i>${k==='budget'?'credits':'/ 100'}</i></strong></div><div class="meter"><b style="width:${state.stats[k]}%;background:${m.color}"></b></div></div>`).join('')}</section>
 <aside class="left-rail"><div class="date-block"><span class="eyebrow">${G.era(state)}</span><h2>Decision ${String(state.turn+1).padStart(2,'0')}<small> / 12</small></h2><div class="session-dots">${Array.from({length:12},(_,i)=>`<span class="${i<state.turn?'done':i===state.turn?'current':''}" title="${i<6?'Mid 2027':'Late 2028'}, decision ${i+1}">${i===6?'│':''}</span>`).join('')}</div></div><div class="mandate"><span class="eyebrow">YOUR GOALS</span><p>${ch.question}</p>${button('See the goals ↗','objectives','mission-link')}<div class="threat"><span>${ch.threat}</span><b>${state.pressure<35?'Contained':state.pressure<60?'Rising':'Acute'}</b></div><div class="meter threat-meter"><b style="width:${state.pressure}%"></b></div></div>
 <nav class="main-nav" aria-label="Strategy panels">${[['map','⌖','Republic'],['policies','⌘','Policy tree'],['evidence','▤','Evidence room'],['council','♙','The council'],['journal','≋','Decision record']].map(([id,icon,name])=>button(`<span>${icon}</span>${name}`,`tab:${id}`,tab===id?'active':'')).join('')}</nav>
 <div class="cabinet"><div class="eyebrow">CABINET ACTIONS <b>${state.actions}/${state.settings.simple?1:2}</b></div><p>Use an optional preparation before choosing your response.</p>${button('Build a coalition <em>3 credits</em>','cabinet:coalition','minor',disabled(G.cabinetError(state,'coalition')))}${button('Reassign reserves <em>+6 credits</em>','cabinet:reserve','minor',disabled(G.cabinetError(state,'reserve')))}${button('Public listening <em>+3 trust</em>','cabinet:outreach','minor',disabled(G.cabinetError(state,'outreach')))}</div>
 <div class="save-status"><span class="status-dot"></span>${lastSaved?'AUTOSAVED LOCALLY':'LOCAL PLAY'}<small>No account. No telemetry.</small></div></aside>
 <div class="map-heading"><span class="eyebrow">REPUBLIC OF TALOS</span><span>Fictional European democracy</span></div><div class="map-controls" aria-label="Map controls">${button('−','zoomout','square','aria-label="Zoom out"')}${button('+','zoomin','square','aria-label="Zoom in"')}${button('⌖','resetcamera','square','aria-label="Reset map view"')}<select aria-label="Map overlay" id="overlay"><option value="normal" ${world?.overlay==='normal'?'selected':''}>Institutions</option><option value="risk" ${world?.overlay==='risk'?'selected':''}>Exposure</option><option value="capacity" ${world?.overlay==='capacity'?'selected':''}>Safeguards</option></select></div>
 <div class="map-caption">Drag to orbit. Scroll to zoom. Select an institution.<span>${world?.overlay==='risk'?'Low exposure  ▰  ▰  ▰  High exposure':'Your decisions affect these public institutions.'}</span></div>
 <div class="build-queue">${state.queue.length?`<span class="eyebrow">INVESTMENTS IN PROGRESS</span>${state.queue.slice(0,3).map(q=>`<p>${(q.kind==='policy'?POLICIES:PROJECTS).find(p=>p.id===q.id).name}<b>${q.due-state.turn} decision${q.due-state.turn===1?'':'s'}</b></p>`).join('')}`:''}</div><aside class="incident-panel" aria-label="Current incident">${incidentPanel()}</aside><section class="district-dock" aria-label="Selected district">${districtDock()}</section>`;
 if(state.phase==='brief')showBrief();else if(state.phase==='era')showEra();else if(state.phase==='resolution')showResolution();else if(state.phase==='chapterEnd')showChapterEnd();else if(state.phase==='finished')showDebrief();else if(tab!=='map')showTab(tab);else if(modal)showModal(modal);else closeModal(false);
}
function disabled(reason){return reason?`disabled title="${esc(reason)}"`:'';}
function landing(){
 const saved=readSaved();app.innerHTML=`<header class="topbar landing-bar"><div class="wordmark">TALOS<span>A REPUBLIC IN YOUR HANDS</span></div>${button('Prologue','prologue','quiet')}${button('Research & credits','sources','quiet')}</header><main class="landing"><div class="landing-copy"><span class="eyebrow">A FRONTIER AI GOVERNANCE GAME</span><h1>Republic<br>of <em>Talos.</em></h1><p>Lead a European democracy through three AI crises in 2027–2028.<br>Keep public services working and people in control.</p><div class="landing-facts"><span>3 possible futures</span><span>36 decisions</span><span>About 2 hours</span></div><div class="start-controls"><label class="eyebrow" for="mode">YOUR CAMPAIGN</label><select id="mode"><option value="campaign">All three futures</option><option value="0">01 / The Capture of Choice</option><option value="1">02 / The Continuity Mandate</option><option value="2">03 / The Open Door Dependency</option></select><details class="difficulty-settings"><summary>Difficulty: standard</summary><div class="difficulty"><label><input type="radio" name="difficulty" value="standard" checked> Standard</label><label><input type="radio" name="difficulty" value="pressure"> Under pressure</label></div></details><label class="start-audio"><input id="start-sound" type="checkbox" checked> English narration, quiet lofi & subtle cues</label><div class="start-buttons">${button('Enter the republic <span>→</span>','new','primary','id="start-game"')}${button('<span aria-hidden="true">▷</span> Watch trailer <small>30s</small>','trailer','secondary trailer-button','id="watch-trailer" aria-haspopup="dialog"')}${saved?button('Resume','resume','secondary'):''}</div></div><p class="small-note">One decision at a time. No countdown.<br>Autosave. Fully offline play and sound.</p></div><div class="landing-scenarios">${CHAPTERS.map(ch=>`<article class="landing-chapter"><span class="chapter-number">${ch.n}</span><div><h3>${ch.title}</h3><p>${ch.tag}</p></div></article>`).join('')}<div class="world-caption">A STRONG COUNTRY IN AN UNEQUAL WORLD<br><span>Mid-2027 / Late-2028</span></div></div></main><footer class="landing-footer"><span>A Talos fellowship project</span><span>Research-informed fiction. Outcomes are not forecasts.</span><span>EDITION 6.2</span></footer>`;
}

function showTrailer(){
 modalShell(`<span class="eyebrow">A FRONTIER AI GOVERNANCE GAME</span><h1 id="trailer-title">Republic of Talos</h1><video data-trailer src="${TRAILER.video}" poster="${TRAILER.poster}" controls playsinline preload="none" tabindex="0" aria-label="Republic of Talos, 30-second trailer"><track kind="captions" src="${TRAILER.captions}" srclang="en" label="English" default></video><p data-trailer-error class="small-note" role="status" hidden>The trailer could not load. You can still close this panel and play.</p><div class="trailer-footer"><p class="small-note">Actual gameplay. AI-generated fictional scenes.<br>Music: <a href="https://www.scottbuckley.com.au/library/the-fury/" target="_blank" rel="noopener noreferrer">The Fury by Scott Buckley</a>, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a>. Edited and mixed.</p>${readSaved()?button('Resume game <span>→</span>','resume','primary'):button('Play the game <span>→</span>','new','primary')}</div>`,'trailer-modal');
 modalRoot.querySelector('[role="dialog"]').setAttribute('aria-labelledby','trailer-title');
 mountTrailer(modalRoot);
}

function incidentPanel(){const ev=G.event(state),ch=CHAPTERS[state.chapter],who=CHARACTERS.find(c=>c.id===ev.speaker),known=state.investigated.includes(ev.id);
 return `<div class="incident-scroll"><div class="incident-top"><span class="eyebrow">COUNCIL BRIEF ${String(state.turn+1).padStart(2,'0')}</span>${chip(state.turn<6?'FIRST SIGNALS':'LATER CONSEQUENCES')}</div><h1>${ev.title}</h1>${sceneOpening(ev)}<div class="byline">${portrait(who.id)}<div><strong>${who.name}</strong><span>${who.role}</span></div>${button('↗',`advisor:${who.id}`,'icon-button','aria-label="Consult adviser"')}</div><p class="incident-body">${ev.body}</p>${ev.callback?`<div class="callback"><span>YOUR EARLIER DECISION</span>${G.flag(state,ev.callback)?ev.yes:ev.no}</div>`:''}<blockquote>“${ev.citizen}”<cite>From the citizens assembly</cite></blockquote>${button('<span>▷</span> View the human impact','film','incident-film-button')}<div class="evidence-strip"><span class="evidence-icon">${known?'✓':'?'}</span><div><strong>${known?'Finding available':'Evidence is incomplete'}</strong><p>${known?'The case review is ready to read.':'Find out what information the service used and what changed for the people affected.'}</p></div>${button(known?'Read':'Investigate',known?'tab:evidence':'investigate','small-button',known?'':disabled(G.canInvestigate(state)))}</div><div class="response-heading"><span class="eyebrow">CHOOSE YOUR RESPONSE</span><small>Choose one response</small></div><div class="responses">${ev.options.map((o,i)=>{const error=G.optionError(state,i);return `<button class="response ${selectedChoice===i?'selected':''} ${error?'unavailable':''}" data-action="choice:${i}" ${disabled(error)}><span class="option-key">${i+1}</span><div><strong>${o.title}</strong><p>${o.desc}</p><div class="effects">${effects(o.effects,true)}</div>${error?`<span class="requirement">${esc(error)}</span>`:''}</div><span class="radio-dot"></span></button>`;}).join('')}</div></div><div class="decision-bar"><div>${selectedChoice<0?button('Review the three responses ↓','responses','review-choices'):state.actions?`${state.actions} cabinet action${state.actions===1?'':'s'} still available`:'Ready for the council decision'}<small>All changes shown are fictional game effects.</small></div>${button('Confirm decision <span>→</span>','enact','primary',selectedChoice<0||state.phase!=='playing'?'disabled':'')}</div>`;
}
function districtDock(){const d=DISTRICTS.find(d=>d.id===state.selected)||DISTRICTS[0],live=state.districts.find(x=>x.id===d.id),pending=state.queue.filter(q=>q.district===d.id);
 return `<div class="district-icon">${d.id==='assembly'?'⌂':d.id==='compute'?'▥':d.id==='court'?'⚖':'⬡'}</div><div class="district-summary"><span class="eyebrow">${d.kind}</span><h3>${d.name}</h3><span class="district-state">${live.projects.length}/3 safeguards <i></i> ${Math.round(live.exposure)} exposure ${pending.length?`<i></i> ${pending.length} building`:''}</span></div><div class="district-projects">${live.projects.length?live.projects.map(p=>chip(PROJECTS.find(x=>x.id===p).name,'good')).join(''):'<p>No local safeguards yet.</p>'}</div>${button('Develop district <span>＋</span>','district','secondary')}`;
}
function modalShell(content,kind='',canClose=true){stopTrailer();stopNarration();stopExplainer();stopFilms();audio.pauseForPanel();modalRoot.innerHTML=`<div class="modal-backdrop ${kind}"><section class="modal ${kind}" role="dialog" aria-modal="true" aria-label="${kind||'Game panel'}">${canClose?button('×','close','close','aria-label="Close panel"'):''}${content}</section></div>`;document.body.classList.add('modal-open');mountFilms(modalRoot);setTimeout(()=>modalRoot.querySelector('button:not([disabled])')?.focus({preventScroll:true}),0);}
function closeModal(reset=true){stopTrailer();stopNarration();stopExplainer();stopFilms();audio.resumeFromPanel();modalRoot.innerHTML='';document.body.classList.remove('modal-open');if(reset){modal=null;tab='map';render();}}
function showBrief(){const ch=CHAPTERS[state.chapter];modalShell(`<div class="brief-banner"><span class="eyebrow">FUTURE ${ch.n} / MID-2027 → LATE-2028</span><h1>${ch.title}</h1><p>${ch.tag}</p><span class="chapter-watermark">${ch.n}</span></div><div class="brief-body">${chapterFilm('opening')}${aiBriefing(false)}<div class="story-person"><span class="eyebrow">${ARCS[state.chapter].person} / ${ARCS[state.chapter].role}</span><p>${ARCS[state.chapter].opening}</p></div><p class="lead">${ch.brief}</p><div class="brief-grid"><div><span class="eyebrow">YOUR TASK</span><h3>${ch.question}</h3><p>${ch.mechanism}</p></div><div class="howto"><span class="eyebrow">TAKE IT ONE DECISION AT A TIME</span><ol><li><b>Read the incident.</b> Open the case evidence whenever useful.</li><li><b>Prepare if you wish.</b> ${state.settings.simple?'One optional investment or support action.':'Up to two cabinet actions.'}</li><li><b>Choose a response.</b> See what changed, then continue.</li></ol></div></div>${state.chapter>0?`<div class="legacy"><b>A different possible future.</b> Talos returns to 2027. ${state.legacy.length?'Up to two completed foundation policies remain available as a game bonus.':'Your earlier decisions belong to a separate scenario.'}</div>`:''}<div class="brief-footer"><small>Twelve decisions, split between 2027 and 2028. No timer.<br>Fictional people, models and incidents.</small>${button('Start this scenario <span>→</span>','begin','primary')}</div></div>`,'brief',false);}

function showEra(){const ch=CHAPTERS[state.chapter];modalShell(`<span class="eyebrow">LATE 2028</span><h1 class="large-serif">Eighteen months later.</h1><p class="lead">Late 2028. ${ch.model[0]} has become ${ch.model[1]}. Your earlier contracts, policies and unresolved cases still apply.</p>${chapterFilm('era')}${aiBriefing(true)}${inheritancePanel()}<p class="story-bridge">${ARCS[state.chapter].bridge}</p><div class="era-values">${['services','rights','autonomy'].map(k=>`<div><strong>${Math.round(state.stats[k])}</strong><span>${METRICS[k].name}</span></div>`).join('')}</div><p>The AI has changed, but the service still uses the staff, contracts and safeguards you put in place. Residents affected by earlier incidents still need help.</p>${button('Enter late 2028 <span>→</span>','begin','primary')}`,'era',false);}
function showResolution(){const r=state.lastResolution,keys=state.settings.simple?['services','rights','autonomy']:Object.keys(r.delta);modalShell(`<span class="eyebrow">YOUR DECISION / DECISION ${state.turn+1}</span><h1>${esc(r.choice)}</h1><p class="lead">${esc(r.desc)}</p>${outcomePanel()}<div class="explainer-invitation"><div><b>Understand the decision</b><p>See who is affected, what caused concern and what each response would change.</p></div>${button('▷ Watch this decision / 42 seconds','film','secondary')}</div><div class="result-metrics ${state.settings.simple?'simple-results':''}">${keys.map(k=>`<div><span>${METRICS[k].short}</span><strong class="${r.delta[k]>=0?'positive':'negative'}">${r.delta[k]>0?'+':''}${r.delta[k]}</strong><small>${Math.round(state.stats[k])} now</small></div>`).join('')}</div><blockquote>“${esc(r.citizen)}”</blockquote>${r.opened.length?`<div class="completed"><b>Now in place</b>${r.opened.map(s=>`<p>✓ ${esc(s)}</p>`).join('')}</div>`:''}${(r.delayed||[]).map(d=>`<div class="delayed"><span class="eyebrow">A LATER CONSEQUENCE OF AN EARLIER CHOICE</span><h4>${esc(d.title)}</h4><p>${esc(d.text)}</p></div>`).join('')}<details><summary>Full result and research basis</summary><div class="effects">${effects(r.delta)}</div><p>Funds: ${Math.round(state.stats.budget)}. Public trust: ${Math.round(state.stats.trust)}. Council support: ${Math.round(state.stats.support)}.</p><p>${esc(r.explanation)} The totals also include government income and investments that have just been completed.</p><p>${esc(DECISION_RESEARCH[G.event(state).id].tradeoff)}</p>${researchLinks(DECISION_RESEARCH[G.event(state).id].sources)}<p class="small-note">The research informs these choices. Their costs and effects are fictional game rules, not measured results.</p></details>${state.stats.trust<30?'<p class="warning">Public trust is low. Listen to residents or choose a response that restores confidence.</p>':''}${state.criticalStreak?`<p class="warning">At least one of trust, services, rights or independence is below 15. Three consecutive decisions with a score this low end the scenario. Current count: ${state.criticalStreak}/3.</p>`:''}<div class="modal-actions"><span>${state.turn===11?'Time to review this scenario.':state.turn===5?'Your choices carry into late 2028.':'Your next brief is ready.'}</span>${button(state.turn===11?'Review this scenario →':state.turn===5?'Move to late 2028 →':'Next decision →','continue','primary')}</div>`,'resolution',false);}

function showChapterEnd(){const r=state.results.at(-1);modalShell(`<span class="eyebrow">SCENARIO ${CHAPTERS[state.chapter].n} / SCENARIO REVIEW</span><h1 class="large-serif">${esc(r.grade)}</h1><p class="lead">${esc(r.summary)}</p>${chapterFilm('ending')}<div class="story-aftermath"><span class="eyebrow">${ARCS[state.chapter].person} / WHAT HAPPENED TO THEM</span><p>${r.win?ARCS[state.chapter].win:ARCS[state.chapter].loss}</p></div>${resultChart(state.chapter)}<div class="review-facts"><span><b>${r.decisions}</b> decisions</span><span><b>${r.investigations}</b> investigations</span><span><b>${r.policies.length}</b> policies</span><span><b>${r.projects}</b> district safeguards</span></div><div class="debrief-prompt"><span class="eyebrow">TAKE THIS BACK TO YOUR INSTITUTION</span><p>${['Who will make sure residents can challenge a decision, and check that mistakes are corrected?','Could you remove every AI account and permission while keeping essential services running?','If you replaced the AI model, would you still depend on the same supplier for documents, staff support or software updates?'][state.chapter]}</p></div><div class="modal-actions">${button('Download decision record','export-debrief','secondary')}${button(state.mode==='campaign'&&state.chapter<2&&state.criticalStreak<3?'Start the next scenario →':'Open campaign debrief →','nextchapter','primary')}</div>`,'chapter-end',false);}
function resultChart(chapter){const rows=state.snapshots.filter(x=>x.chapter===chapter);if(!rows.length)return '';const colors={services:'#8eb9a7',rights:'#a5bfd1',autonomy:'#c0afd7',trust:'#d6b474'};return `<div class="chart"><svg viewBox="0 0 640 180" role="img" aria-label="Public trust, services, rights and autonomy across this history">${[25,50,75].map(y=>`<line x1="32" y1="${160-y*1.4}" x2="620" y2="${160-y*1.4}" stroke="#ffffff16"/><text x="3" y="${164-y*1.4}">${y}</text>`).join('')}${Object.entries(colors).map(([k,c])=>`<polyline points="${rows.map((r,i)=>`${32+i*588/11},${160-r.stats[k]*1.4}`).join(' ')}" fill="none" stroke="${c}" stroke-width="3"/>`).join('')}<text x="32" y="178">DECISION 1</text><text x="548" y="178">DECISION 12</text></svg><div class="chart-legend">${Object.entries(colors).map(([k,c])=>`<span><i style="background:${c}"></i>${METRICS[k].short}</span>`).join('')}</div></div>`;}
function showTab(which){modal=which;const fn={policies:showPolicies,evidence:showEvidence,council:showCouncil,journal:showJournal};fn[which]?.();}
function showPolicies(){modalShell(`<span class="eyebrow">BUILD THE INSTITUTION BEFORE THE CRISIS</span><h1>Policy tree</h1><p>Starting a policy uses one preparation and costs public funds. Its benefits begin after the number of decisions shown. Some policies require you to complete an earlier policy first.</p><div class="policy-grid">${['Evidence','Rights','Control','Resilience'].map(branch=>`<section class="policy-branch"><h3>${branch}</h3>${POLICIES.filter(p=>p.branch===branch).map(p=>{const active=state.policies.includes(p.id),pending=state.queue.find(q=>q.id===p.id&&q.kind==='policy'),error=G.policyError(state,p.id);return `<article class="policy-card ${active?'enacted':''} ${pending?'building':''}"><span class="policy-level">${active?'✓ ACTIVE':pending?`IN PROGRESS / ${pending.due-state.turn} DECISION${pending.due-state.turn===1?'':'S'}`:`TIER ${p.tier+1}`}</span><h4>${p.name}</h4><p>${p.desc}</p><span class="policy-bonus">${p.bonus}</span><div class="effects">${effects(p.effect,true)}</div>${button(active?'Enacted':pending?'Implementing':`Fund: ${p.cost} credits →`,`research:${p.id}`,'small-button',disabled(error))}<small>${p.turns} decision${p.turns===1?'':'s'}${p.requires.length?` / Requires ${POLICIES.find(x=>x.id===p.requires[0]).name}`:''}</small></article>`;}).join('')}</section>`).join('')}</div>`,'policy-modal');}
function showEvidence(){const e=G.event(state),known=state.investigated.includes(e.id),m=MODEL_CARDS[state.chapter];modalShell(`<span class="eyebrow"><a href="https://miguelguerrero.eu/agencytransfer/" target="_blank" rel="noopener noreferrer">ERA: CAPABILITY → DEPLOYMENT → EFFECT ↗</a></span><h1>What do we actually know?</h1><p class="lead">${e.title}</p>${aiBriefing(state.turn>=6)}<div class="evidence-grid"><article><span class="evidence-stage">01 / CAPABILITY</span><h3>What can the system do?</h3><p>${CHAPTERS[state.chapter].mechanism}</p><small>The research explains why this risk is worth investigating. The incident itself is fictional.</small></article><article><span class="evidence-stage">02 / DEPLOYMENT</span><h3>What happened here?</h3><p>${e.signal}</p><small>Check the application settings, information sources, connected tools and permissions.</small></article><article class="${known?'found':''}"><span class="evidence-stage">03 / EFFECT</span><h3>What changed for people?</h3><p>${EFFECT_NOTES[e.id]}${known?`<br><br><b>Investigation finding:</b> ${e.finding}`:'<br><br>Read the case finding to see what the investigation found.'}</p>${!known?button(`${state.settings.simple?'Read case finding / free':`Investigate / ${G.investigateCost(state)} credits`}`,'investigate','primary',disabled(G.canInvestigate(state))):chip('CASE FINDING AVAILABLE','good')}</article></div><details class="model-card"><summary>${m.name} <span>Fictional model card</span></summary><div class="model-grid">${[['Type of system',m.family],['What it can access',m.access],['Useful function',m.benefit],['Scenario risk',m.risk],['What to test',m.check],['Still unknown',m.unknown]].map(([k,v])=>`<div><span class="eyebrow">${k}</span><p>${v}</p></div>`).join('')}</div><p class="boundary">${m.boundary}</p></details><div class="modal-actions"><small>Case findings describe events invented for this game.<br>Numerical effects are game rules, not research estimates.</small>${button('Research sources','sources','secondary')}</div>`,'evidence-modal');}
function showCouncil(){const c=CHARACTERS.find(c=>c.id===selectedAdvisor);modalShell(`<span class="eyebrow">DIFFERENT RESPONSIBILITIES, ONE COUNCIL DECISION</span><h1>The council</h1><div class="council-layout"><div class="adviser-grid">${CHARACTERS.map(a=>`<button class="adviser-card ${a.id===c.id?'selected':''}" data-action="advisor:${a.id}">${portrait(a.id)}<strong>${a.name}</strong><span>${a.role}</span></button>`).join('')}</div><article class="adviser-detail">${portrait(c.id,'large')}<span class="eyebrow">${c.role}</span><h2>${c.name}</h2><p class="mandate-line">${c.mandate}</p><blockquote>“${G.advice(state,c.id)}”</blockquote><p>${c.bio}</p><div class="adviser-meter"><span>${METRICS[c.metric].name}</span><b>${Math.round(state.stats[c.metric])}/100</b></div><p class="small-note">Advisers have different responsibilities. Listen to their reasons and weigh the needs they represent. You still make the decision.</p>${button('Negotiate council support / 3 credits','cabinet:coalition','secondary',disabled(G.cabinetError(state,'coalition')))}</article></div>`,'council-modal');}
function showJournal(){modalShell(`<span class="eyebrow">YOUR DECISIONS SO FAR</span><h1>Decision record</h1><p>Your choices, investigations and investments are saved locally.</p><div class="journal-list">${[...state.history].reverse().map(h=>`<article><span class="eyebrow">SCENARIO ${h.chapter+1} / DECISION ${h.turn+1} / ${h.type}</span><h3>${esc(h.choice||h.title||({investigation:'Case reviewed',project:'District project funded',policy:'A policy started',cabinet:'Preparation'})[h.type])}</h3><p>${esc(h.text)}</p>${h.delta?`<div class="effects">${effects(h.delta,true)}</div>`:''}</article>`).join('')||'<p class="empty">You have not made a decision yet. Your first case is ready.</p>'}</div><div class="modal-actions">${button('Export decision record','export-debrief','secondary')}${button('Export save','export-save','secondary')}</div>`,'journal-modal');}
function showDistrict(){const d=DISTRICTS.find(x=>x.id===state.selected),live=state.districts.find(x=>x.id===d.id);modalShell(`<span class="eyebrow">${d.kind}</span><h1>${d.name}</h1><p class="lead">${d.desc}</p><div class="district-modal-status"><span>Local exposure <b>${Math.round(live.exposure)}/100</b></span><span>Safeguards <b>${live.projects.length}/3</b></span><span>Cabinet actions <b>${state.actions}/2</b></span></div><div class="project-grid">${PROJECTS.map(p=>{const done=live.projects.includes(p.id),pending=state.queue.find(q=>q.kind==='project'&&q.id===p.id&&q.district===d.id),error=G.projectError(state,d.id,p.id);return `<article class="project-card ${done?'enacted':''}"><span class="project-icon">${p.icon}</span><div><h3>${p.name}</h3><p>${p.desc}</p><div class="effects">${effects(p.effect,true)}<span class="effect positive">−${p.protect} local exposure</span></div><small>${p.turns} decision${p.turns===1?'':'s'} to open. Uses one of three local slots.</small></div>${button(done?'Built ✓':pending?`${pending.due-state.turn} decisions`:`${p.cost} credits →`,`build:${p.id}`,'secondary',disabled(error))}</article>`;}).join('')}</div>`,'district-modal');}
function showSources(){modalShell(`<span class="eyebrow">RESEARCH / REVIEWED 18 OCTOBER 2026</span><h1>What the game is built on.</h1><p class="lead">The game draws on research into AI persuasion, model testing, government oversight and European regulation. Each decision explains which studies informed it and what they do not prove. Talos, its people, incidents and numerical outcomes are fictional.</p><div class="era-source"><h3><a href="https://miguelguerrero.eu/agencytransfer/" target="_blank" rel="noopener noreferrer">ERA: Capability, Deployment, Effect ↗</a></h3><p>What can the system do? How is it used? What actually changed for people? These questions guide the game.</p></div><p class="small-note"><a href="https://miguelguerrero.eu/agencytransfer/references/" target="_blank" rel="noopener noreferrer">Explore Miguel Guerrero’s supporting research collection ↗</a></p><div class="sources-list">${SOURCES.map(s=>`<article><span class="eyebrow">${s.type} / ${s.year}</span><h3><a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.name} ↗</a></h3><p>${s.finding}</p><p class="source-limit"><b>Limit:</b> ${s.limit}</p><small>Design use: ${s.use}</small></article>`).join('')}</div><p class="boundary">Here, “superpersuasion” means the possibility that AI could become unusually effective at influencing people. It does not mean that people can be controlled at will. Changing an opinion, giving a biased answer, manipulating a choice and causing harm are different things. The research does not predict the events or scores in this game. The organisations cited have not endorsed the game.</p><p class="small-note">Game authored by <a href="https://miguelguerrero.eu" target="_blank" rel="noopener noreferrer">Miguel Guerrero</a>. Original Blender world. Three.js: MIT. Barlow: SIL Open Font License. Optional films are AI-generated fictional dramatizations.</p><p class="small-note">Original soundtrack: Night Session, composed for this game. Quiet lofi, bundled for offline play. Original procedural sound effects. Twenty-seven cinematic illustrations and eight moving scenes show fictional people and incidents. The images after a decision reflect your choice. Films between phases reflect the decisions you have made and the state of Talos. Each of the 36 decisions has its own 42-second explainer, with human scenes, animated diagrams and a comparison of the three responses. They include natural English AI voice narration, readable captions and quiet music. Listening is optional.</p>`,'sources-modal');}

function showHelp(){modalShell(`<span class="eyebrow">HOW TO PLAY</span><h1>Govern frontier AI. See what changes.</h1><div class="help-steps"><article><b>1</b><h3>Read one incident</h3><p>Understand what happened and who is affected. Read case evidence or ask an adviser whenever useful.</p></article><article><b>2</b><h3>Prepare if you wish</h3><p>In the simple view, you can make one investment, find extra funds or build support. Reading case findings is free. Preparation is optional.</p></article><article><b>3</b><h3>Make one decision</h3><p>Select one of three responses, then confirm. Read the result before continuing.</p></article></div><div class="help-grid"><div><h3>Three things to protect</h3><p><b>Services:</b> can people get essential help?<br><b>Rights:</b> can they choose, question and appeal?<br><b>Independence:</b> can Talos inspect and replace its systems?</p><p>Funds pay for action. Trust and council support are available in Republic status; you will see a warning when they need attention.</p><h3>Plan a little ahead</h3><p>Investments take one to three decisions to complete. Your chosen response has an immediate effect, and some consequences appear later.</p></div><div><h3>Success and failure</h3><p>Open Your goals for the conditions you need to meet. The scenario ends early if any of trust, services, rights or independence stays below 15 for three consecutive decisions.</p><h3>Your pace</h3><p>Three separate futures, 12 decisions each, with a jump from 2027 to 2028. About two hours is an estimate. You can stop and resume.</p><p><kbd>1</kbd><kbd>2</kbd><kbd>3</kbd> select a response. <kbd>E</kbd> evidence. <kbd>C</kbd> council. <kbd>Esc</kbd> close.</p></div></div><div class="modal-actions">${button('Read the prologue','prologue','secondary')}${button('Back to the game','close','primary')}</div>`,'help-modal');}

function showMenu(){modalShell(`<span class="eyebrow">REPUBLIC OF TALOS</span><h1>Pause and return when you are ready.</h1><p>Your progress is saved on this browser.</p><div class="menu-grid">${button('Return to the republic','close','primary')}${button('Republic status','stats','secondary')}${button('Your goals','objectives','secondary')}${button('Introduction & your role','prologue','secondary')}${button('How to play','help','secondary')}${button('Research & credits','sources','secondary')}${button('Music & sound','sound-settings','secondary')}${button('Decision record','tab:journal','secondary')}${button('All investments','tab:policies','secondary')}${button(state?.settings.simple?'Show detailed strategy view':'Use simple view','view-mode','secondary')}${button('Export save','export-save','secondary')}${button('Import save','import-save','secondary')}${button(state?.settings.reducedMotion?'Enable ambient movement':'Reduce ambient movement','motion','secondary')}${button('Return to title','title','secondary')}</div><p class="small-note">Starting a new campaign replaces this browser's autosave. Export first to keep both. Music and sound are bundled and work offline.</p>`,'menu-modal');}

function showDebrief(){const d=G.debrief(state);modalShell(`<span class="eyebrow">YOUR CAMPAIGN / FINAL REVIEW</span><h1 class="large-serif">What remains in human hands?</h1><p class="lead">${state.results.filter(r=>r.win).length} of ${state.results.length} scenarios met their goals. You made ${d.decisions.length} decisions.</p><div class="ending-grid">${state.results.map(r=>`<article><span class="eyebrow">${CHAPTERS[r.chapter].n} / ${esc(r.title)}</span><h3>${esc(r.grade)}</h3><p>${esc(r.summary)}</p><p class="ending-person">${r.win?ARCS[r.chapter].win:ARCS[r.chapter].loss}</p><div class="effects">${['services','rights','autonomy'].map(k=>chip(`${METRICS[k].short} ${Math.round(r.stats[k])}`)).join('')}</div></article>`).join('')}</div><h3>Questions for your own organisation</h3><ol class="debrief-questions">${d.questions.map(q=>`<li>${q}</li>`).join('')}</ol><p class="boundary">Your results reflect the game\'s authored rules. They do not estimate real-world probabilities or establish that any policy will have the same effect outside this exercise.</p><div class="modal-actions">${button('Download your debrief','export-debrief','primary')}${button('Return to title','title','secondary')}</div>`,'debrief-modal',false);}
function showObjectives(){const ch=CHAPTERS[state.chapter],s=state.stats;const relevant=state.chapter===0?s.rights:state.chapter===1?s.autonomy:Math.min(s.rights,s.autonomy);const protection=state.chapter===0?(state.policies.includes('appeals')||G.flag(state,'choiceCharter')||G.flag(state,'outreachRepair')):state.chapter===1?(state.policies.includes('sunset')||G.flag(state,'revocableCharter')||G.flag(state,'exitExercised')):(state.policies.includes('diversify')||G.flag(state,'independenceCompact')||G.flag(state,'verifiedExit'));const goals=[['Keep trust, services, rights and independence at 30 or above',Math.min(s.trust,s.services,s.rights,s.autonomy)>=30],['Keep services at 45 or above',s.services>=45],[state.chapter===0?'Keep rights at 45 or above':state.chapter===1?'Keep independence at 45 or above':'Keep both rights and independence at 45 or above',relevant>=45],['Put a relevant safeguard into practice',!!protection]];modalShell(`<span class="eyebrow">YOUR GOALS / SCENARIO ${ch.n}</span><h1>${ch.question}</h1><p class="lead">Meet these conditions when you finish the twelfth decision.</p><div class="goal-list">${goals.map(([label,met])=>`<p class="${met?'met':''}"><b>${met?'✓':'○'}</b>${label}<span>${met?'Currently met':'Not yet met'}</span></p>`).join('')}</div><p><b>A qualifying safeguard:</b> ${['Complete “Provide a person to review decisions”, contact and help affected households in decision 10, or choose “Fund appeals and independent review” in decision 12.','Complete “Set expiry dates and independent approvals”, choose “Finish the full exit rehearsal” in decision 11, or choose “Keep access conditional and withdrawable” in decision 12.','Complete “Fund independent staff and suppliers”, choose “Launch the tested essential service” in decision 11, or choose “Fund independent advice and a tested ability to switch” in decision 12.'][state.chapter]}</p><p class="boundary">The scenario ends early after three consecutive decisions with any of trust, services, rights or independence below 15. Policies only count once completed. These thresholds are game rules, not measures of whether a real government is succeeding.</p>`,'objectives-modal');}
function showFilm(){
 const ev=G.event(state),f=EXPLAINER_MANIFEST.films[ev.id],media=EXPLAINER_MEDIA[ev.id];
 modalShell('<span class="eyebrow">DECISION EXPLAINER / '+esc(f.id.toUpperCase())+' / '+f.duration+' SECONDS</span><h1>'+esc(f.title)+'</h1><p class="lead">'+(state.phase==='resolution'?'You chose: '+esc(state.lastResolution.choice)+'. The film compares all three responses; it does not change your choice.':'See what happened, who is affected and what each response could change.')+'</p><video data-decision-film="'+f.id+'" src="'+media.video+'" poster="'+media.poster+'" controls preload="none" playsinline aria-label="'+esc(f.title)+' decision explainer"></video><p data-film-error hidden class="warning">This film could not load. The full explainer is available in the transcript below.</p><p class="small-note">Press play for English narration. Music stays quiet; captions are always available. The people and events are fictional. The film compares possible consequences, not predictions.</p><details class="explainer-transcript"><summary>Read the explainer</summary>'+f.segments.map(s=>'<p><b>'+Math.floor(s.start)+'s</b> '+esc(s.text)+'</p>').join('')+'</details><details><summary>Research behind this film</summary>'+policyLens(ev.id)+researchCards(DECISION_RESEARCH[ev.id].sources)+'</details><div class="modal-actions">'+button(state.phase==='resolution'?'Return to your result':'Return to your decision','return-film','primary')+button(audio.on?'♫ Sound on':'♫ Sound off','sound','quiet')+'</div>','film-modal');
 mountExplainer(modalRoot,audio);
}
function showModal(which){({prepare:showPreparation,'research-basis':showDecisionResearch,stats:showStats,district:showDistrict,sources:showSources,help:showHelp,menu:showMenu,film:showFilm,objectives:showObjectives,'sound-settings':showSound})[which]?.();}
function exportDebrief(){const lines=['REPUBLIC OF TALOS','Decision record and debrief','Research-informed fiction. Numerical outcomes are game rules, not forecasts.','',...state.results.flatMap(r=>[r.title,r.grade,r.summary,JSON.stringify(r.stats),'']),...state.history.map(h=>`Scenario ${h.chapter+1}, decision ${h.turn+1}: ${h.choice||h.type}. ${h.text}${h.type==='decision'?' Story: '+storyAfter(EVENTS[h.chapter][h.turn],h.choice):''}`),'','Questions for your institution',...G.debrief(state).questions.map((q,i)=>`${i+1}. ${q}`),'','Evidence sources',...SOURCES.map(s=>`${s.name}: ${s.url}`)];download('Talos_Mandate_Debrief.txt',lines.join('\n'),'text/plain');}
function perform(fn,cue='click'){const r=fn();if(!r.ok){toast(r.error);return;}audio.effect(cue);store();render();if(r.text)toast(r.text);}
async function action(a){
 const [name,id]=a.split(':');
 if(name==='sound-settings'){modal='sound-settings';showSound();return;}
 if(name==='prologue-next'){audio.effect('page');prologueStep=Math.min(2,prologueStep+1);showPrologue();return;}
 if(name==='prologue-back'){prologueStep=Math.max(0,prologueStep-1);showPrologue();return;}
 if(name==='prologue-finish'){prologueActive=false;if(state){state.settings.prologueSeen=true;store();}modal=null;closeModal(false);render();return;}
 if(name==='prologue'){prologueStep=0;prologueActive=true;showPrologue();return;}
 if(name==='prepare'){modal='prepare';showPreparation();return;}
 if(name==='research-basis'){modal='research-basis';showDecisionResearch();return;}
 if(name==='stats'){modal='stats';showStats();return;}
 if(name==='view-mode'){state.settings.simple=!state.settings.simple;state.actions=Math.min(state.actions,1);store();modal=null;tab='map';render();return;}
 if(['begin','enact','continue','nextchapter','title'].includes(name)){clearTimeout(toastTimer);$('#toast').classList.remove('show');}
 if(name==='new'){const soundWanted=$('#start-sound').checked;void audio.enable(soundWanted);const mode=$('#mode').value,difficulty=$('input[name=difficulty]:checked').value;state=G.createGame({mode:mode==='campaign'?'campaign':'scenario',chapter:mode==='campaign'?0:+mode,difficulty,seed:Math.floor(Math.random()*4294967295),simple:true});state.settings.sound=audio.on;state.settings.reducedMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;tab='map';modal=null;selectedChoice=-1;prologueActive=true;prologueStep=0;store();render();return;}
 if(name==='resume'){state=readSaved();if(!state)return toast('No valid save is available.');tab='map';modal=null;selectedChoice=-1;state.settings.sound=false;audio.enable(false);prologueActive=!state.settings.prologueSeen&&state.phase==='brief'&&state.totalSessions===0;render();return;}
 if(name==='title'){prologueActive=false;store();state=null;tab='map';modal=null;selectedChoice=-1;audio.enable(false);closeModal(false);render();return;}
 if(name==='trailer'){modal='trailer';showTrailer();return;}
 if(name==='close'&&modal==='trailer'){closeModal(false);modal=null;$('#watch-trailer')?.focus({preventScroll:true});return;}
 if(name==='sources'||name==='help'||name==='menu'){modal=name;showModal(name);return;}
 if(name==='return-film'||(name==='close'&&modal==='film')){modal=null;tab='map';closeModal(false);render();return;}
 if(name==='close'){if(prologueActive)return;if(state&&['brief','era','resolution','chapterEnd','finished'].includes(state.phase))return;closeModal();return;}
 if(!state)return;
 if(name==='begin'){audio.effect('horizon');G.prepare(state);modal=null;tab='map';selectedChoice=-1;store();render();return;}
 if(name==='responses'){$('.responses').scrollIntoView({block:'start',behavior:state.settings.reducedMotion?'instant':'smooth'});return;}
 if(name==='choice'){selectedChoice=+id;audio.click();const scroll=$('.incident-scroll')?.scrollTop||0;render();if($('.incident-scroll'))$('.incident-scroll').scrollTop=scroll;return;}
 if(name==='enact'){perform(()=>G.choose(state,selectedChoice),'decision');selectedChoice=-1;return;}
 if(name==='continue'){audio.effect(state.turn===5?'horizon':'page');G.continueSession(state);selectedChoice=-1;modal=null;tab='map';store();render();return;}
 if(name==='nextchapter'){G.nextChapter(state);selectedChoice=-1;modal=null;tab='map';store();render();return;}
 if(name==='tab'){tab=id;modal=id==='map'?null:id;render();return;}
 if(name==='advisor'){selectedAdvisor=id;tab='council';modal='council';showCouncil();return;}
 if(name==='district'){modal='district';showDistrict();return;}
 if(name==='film'){modal='film';showFilm();return;}
 if(name==='objectives'){modal='objectives';showObjectives();return;}
 if(name==='investigate'){const r=G.investigate(state);if(!r.ok)return toast(r.error);audio.effect('evidence');store();modal='evidence';tab='evidence';render();return;}
 if(name==='build'){modal=null;tab='map';perform(()=>G.buildProject(state,state.selected,id));return;}
 if(name==='research'){modal=null;tab='map';perform(()=>G.research(state,id));return;}
 if(name==='cabinet'){modal=null;tab='map';perform(()=>G.cabinet(state,id));return;}
 if(name==='sound'){await audio.enable(!audio.on);if(state)state.settings.sound=audio.on;store();if(modal==='sound-settings')showSound();const activeFilm=document.querySelector('[data-decision-film]');if(activeFilm)activeFilm.muted=!audio.on;return;}
 if(name==='motion'){state.settings.reducedMotion=!state.settings.reducedMotion;store();render();return;}
 if(name==='export-save'){download('Talos_Mandate_Save.json',G.saveGame(state));toast('Portable save exported.');return;}
 if(name==='import-save'){$('#import-file').click();return;}
 if(name==='export-debrief'){exportDebrief();return;}
 if(name==='zoomout')world.distance=Math.min(1.45,world.distance+.12);
 if(name==='zoomin')world.distance=Math.max(.66,world.distance-.12);
 if(name==='resetcamera')world.reset();
}
function researchLinks(ids){return `<div class="research-links">${ids.map(id=>{const s=SOURCES.find(x=>x.id===id);return `<a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.name} ↗</a>`;}).join('')}</div>`;}
function showDecisionResearch(){const e=G.event(state),r=DECISION_RESEARCH[e.id];modalShell(`<span class="eyebrow">THE RESEARCH BEHIND THIS DECISION</span><h1>${e.title}</h1><p class="lead">${r.question}</p><p>${r.tradeoff}</p>${policyLens(e.id)}${researchCards(r.sources)}<details><summary>Compare the three responses</summary>${e.options.map(o=>`<article class="choice-research"><h3>${o.title}</h3><p>${o.desc}</p><div class="effects">${effects(o.effects)}</div></article>`).join('')}</details><p class="boundary">These sources help explain the problem and what to investigate. The game’s responses and scores are fictional. The papers do not prove that these policies would have the same effects in real life.</p>${button('Return to the decision','close','primary')}`,'research-modal');}

function sceneFigure(ev,wide=false){const sc=SCENES[ev.id];return '<figure class="scene-figure '+(wide?'wide':'')+'"><img src="'+SCENE_IMAGES[sc.image]+'" alt="Fictional illustration: '+esc(sc.place)+'" width="1280" height="720" decoding="async"><figcaption><span>'+esc(sc.place)+'</span><small>AI-generated fiction</small></figcaption></figure>';}
function sceneOpening(ev){return sceneFigure(ev);}
function showSound(){modalShell('<span class="eyebrow">THE SOUND OF TALOS</span><h1>Music and sound</h1><p>Night Session is the quiet background music included in the game. Sound pauses when you leave this tab.</p><div class="sound-controls">'+button(audio.on?'Mute all sound':'Enable sound','sound','secondary')+'<label for="score-volume">Background music & cues <output id="score-level">'+audio.volume+'%</output></label><input id="score-volume" type="range" min="0" max="30" value="'+audio.volume+'"><label class="sfx-label"><input id="sfx-enabled" type="checkbox" '+(audio.sfx?'checked':'')+'> Quiet sound effects for case findings, decisions and changes of year</label></div><p class="small-note">Music and sound are included in both the web and offline editions.</p>','sound-settings');}

function showPrologue(){const pages=[
{kicker:'01 / YOUR COUNTRY AND ROLE',title:'Welcome to the<br>Republic of Talos.',body:`<p class="lead">It is mid-2027. You chair the elected government's council on AI and public services. Talos is a prosperous, medium-sized European democracy.</p><p>Talos has good universities, skilled workers and public services that people rely on. It depends on larger powers for advanced computer chips, cloud services, energy and security. It can afford safeguards and build partnerships, but it cannot replace every outside supplier overnight.</p><p>Your council decides how government uses AI. You can fund staff, set conditions in contracts and restrict a service when people may be harmed. Courts, elected representatives, journalists and residents can challenge your decisions.</p><div class="prologue-callout">Your task is to keep essential services working, protect residents' rights and make sure Talos can change course when it needs to.</div>`},
{kicker:'02 / THE AI YOU WILL GOVERN',title:'Useful systems with<br>real responsibilities.',body:`${aiPrimer()}<p>Government departments want to use these systems because they can answer questions quickly and help staff with complex work. Problems arise when a convincing answer leaves out an important option, or when an automated service gains permissions that people cannot easily take back.</p><div class="prologue-people">${['nora','leon','samir','ines'].map(id=>{const c=CHARACTERS.find(x=>x.id===id);return `<div>${portrait(id)}<strong>${c.name}</strong><small>${c.role}</small></div>`;}).join('')}</div><p>Your advisers represent residents, public services, oversight bodies and suppliers. They will explain different needs and costs. Listen to their reasons, then make your decision.</p><div class="prologue-callout">Ask three questions: what can the AI do, how is the service using it, and what has actually changed for people?</div>`},
{kicker:'03 / HOW TO PLAY',title:'Three possible futures,<br>one decision at a time.',body:`<div class="prologue-histories"><p><b>01 / The Capture of Choice.</b> An advice service steers residents towards paid help and leaves out free alternatives.</p><p><b>02 / The Continuity Mandate.</b> An advanced AI behaves differently during tests and seeks lasting access to government systems and resources.</p><p><b>03 / The Open Door Dependency.</b> An authoritarian government subsidises cheap AI services, then uses the resulting dependence to influence public institutions.</p></div><p>Each scenario starts again in mid-2027. You make six decisions, then see how the situation develops through six more decisions in late 2028. These are three separate possibilities, not one predicted history.</p><div class="prologue-callout"><b>Read what happened, prepare if you wish, then choose one response.</b><br>In the simple view, you have one optional preparation before each decision. Case findings are free to read. You can open the detailed tools from the menu.</div><p class="small-note">There is no timer, and your progress saves automatically. All 36 decisions take about two hours, depending on how much you explore. The research informs the questions; the incidents and scores are fictional.</p>`}
];const p=pages[prologueStep];modalShell(`<span class="eyebrow">FRONTIER AI GOVERNANCE / PROLOGUE</span><div class="prologue-progress">${pages.map((_,i)=>`<i class="${i<=prologueStep?'active':''}"></i>`).join('')}</div><span class="eyebrow">${p.kicker}</span><h1 class="large-serif">${p.title}</h1>${prologueStep===0?filmMarkup(cinematicStory(state||G.createGame(),'prologue'),SCENE_IMAGES,CINEMA,state?.settings.reducedMotion??matchMedia('(prefers-reduced-motion: reduce)').matches):''}${narrationMarkup(prologueStep)}${p.body}<div class="modal-actions">${prologueStep?button('← Back','prologue-back','secondary'):'<span>Take a moment to meet your country.</span>'}${button(prologueStep<2?'Continue →':state?(state.totalSessions||state.phase==='playing'?'Return to your game →':'Meet your first challenge →'):'Return to title →',prologueStep<2?'prologue-next':'prologue-finish','primary')}</div>`,'prologue-modal',false);mountNarration(modalRoot,audio);}
function renderSimple(){
 const ch=CHAPTERS[state.chapter];
 app.innerHTML=`<header class="topbar simple-topbar"><button class="wordmark" data-action="menu">TALOS<span>REPUBLIC OF TALOS</span></button><div class="simple-turn">${G.era(state)}<strong>Decision ${state.turn+1} of 12</strong></div><div class="top-tools">${button(audio.on?'♫ Sound on':'♫ Sound off','sound','quiet')}${button('Menu','menu','quiet')}</div></header><section class="simple-metrics" aria-label="Republic status">${['services','rights','autonomy'].map(k=>`<button data-action="stats" class="simple-metric ${state.stats[k]<30?'danger':''}"><span>${METRICS[k].short}</span><strong>${Math.round(state.stats[k])}</strong><div class="meter"><b style="width:${state.stats[k]}%;background:${METRICS[k].color}"></b></div></button>`).join('')}<button class="simple-funds" data-action="stats"><small>Funds</small><strong>${Math.round(state.stats.budget)}</strong><span>Details ↗</span></button></section><section class="simple-context"><span class="eyebrow">FUTURE ${ch.n}</span><h2>${ch.title}</h2><p>${ch.question}</p>${button('Your goals ↗','objectives','mission-link')}</section><div class="map-controls">${button('−','zoomout','square','aria-label="Zoom out"')}${button('+','zoomin','square','aria-label="Zoom in"')}${button('⌖','resetcamera','square','aria-label="Reset map view"')}</div><div class="simple-map-note">A prosperous democracy that depends on larger powers for technology.<br><span>Select a district to explore Talos.</span></div><div class="simple-map-dock"><div><small>${DISTRICTS.find(x=>x.id===state.selected).kind}</small><strong>${DISTRICTS.find(x=>x.id===state.selected).name}</strong></div>${button('Explore district','district','secondary')}</div><nav class="simple-tools" aria-label="Optional support">${button('Case evidence','tab:evidence','secondary')}${button('Ask the council','tab:council','secondary')}${button(state.actions?'Prepare / optional':'Preparation complete','prepare','secondary')}</nav><aside class="incident-panel" aria-label="Current incident">${simpleIncident()}</aside>`;
 if(state.phase==='brief')showBrief();else if(state.phase==='era')showEra();else if(state.phase==='resolution')showResolution();else if(state.phase==='chapterEnd')showChapterEnd();else if(state.phase==='finished')showDebrief();else if(tab!=='map')showTab(tab);else if(modal)showModal(modal);else closeModal(false);
}
function simpleIncident(){const ev=G.event(state),who=CHARACTERS.find(c=>c.id===ev.speaker),known=state.investigated.includes(ev.id);return `<div class="incident-scroll"><div class="incident-top"><span class="eyebrow">YOUR CURRENT DECISION</span><small>${lastSaved?'Saved automatically':'Local play'}</small></div><h1>${ev.title}</h1>${sceneOpening(ev)}<div class="byline">${portrait(who.id)}<div><strong>${who.name}</strong><span>${who.role}</span></div>${button('Ask ↗',`advisor:${who.id}`,'icon-button','aria-label="Consult adviser"')}</div><p class="incident-body">${ev.body}</p>${ev.callback?`<details class="earlier-choice"><summary>Your earlier choice matters</summary><p>${G.flag(state,ev.callback)?ev.yes:ev.no}</p></details>`:''}<div class="simple-evidence-actions">${button(known?'Read the case finding':'Read case finding / free',known?'tab:evidence':'investigate','small-button')}${button('Why this dilemma?','research-basis','text-link')}${button('▷ 42-second explainer','film','text-link')}</div>${state.stats.trust<30?'<p class="warning">Public trust is low. Listen to residents or help people affected by earlier mistakes.</p>':''}${state.stats.support<45?'<p class="warning">Council support is low. Use Prepare to negotiate support from council members.</p>':''}<div class="response-heading"><span class="eyebrow">WHAT WILL YOU DO?</span></div><div class="responses">${ev.options.map((o,i)=>{const error=G.optionError(state,i);return `<button class="response ${selectedChoice===i?'selected':''}" data-action="choice:${i}" ${disabled(error)}><span class="option-key">${i+1}</span><div><strong>${o.title}</strong><p>${o.desc}</p>${selectedChoice===i?`<div class="effects">${effects(Object.fromEntries(Object.entries(o.effects).filter(([k])=>['budget','services','rights','autonomy'].includes(k))),true)}</div>`:''}${error?`<span class="requirement">${esc(error)}</span>`:''}</div><span class="radio-dot"></span></button>`;}).join('')}</div><details class="human-story"><summary>The human story</summary><p class="scene-beat">${esc(SCENES[ev.id].beat)}</p><blockquote>“${ev.citizen}”<cite>From the citizens assembly</cite></blockquote>${button('▷ Watch this decision / 42 seconds','film','incident-film-button')}</details></div><div class="decision-bar"><div>${selectedChoice<0?button('Review the three responses ↓','responses','review-choices'):'Review your choice, then confirm.'}<small>You set the pace. Consequences can carry into later decisions.</small></div>${button('Confirm decision <span>→</span>','enact','primary',selectedChoice<0||state.phase!=='playing'?'disabled':'')}</div>`;}
function showPreparation(){
 const wanted=[['appeals','records','repair','portable'],['inventory','sunset','records','blind','revoke'],['portable','diversify','records','appeals']][state.chapter];
 const policy=wanted.map(id=>POLICIES.find(p=>p.id===id)).find(p=>!state.policies.includes(p.id)&&!state.queue.some(q=>q.id===p.id)&&p.requires.every(id=>state.policies.includes(id)));
 const support=state.stats.support<48;const kind=support?'coalition':'reserve';
 modalShell(`<span class="eyebrow">ONE OPTIONAL PREPARATION</span><h1>Prepare before you decide.</h1><p>You have <b>${state.actions}</b> optional preparation${state.actions===1?'':'s'} available. Choose one, or return directly to your decision. Reading case evidence is free.</p><div class="preparation-list">${policy?`<article><span class="eyebrow">STRENGTHEN AN INSTITUTION</span><h3>${policy.name}</h3><p>${policy.desc}</p><small>${policy.cost} credits. Ready after ${policy.turns} decision${policy.turns===1?'':'s'}.</small>${button('Fund this safeguard',`research:${policy.id}`,'secondary',disabled(G.policyError(state,policy.id)))}</article>`:''}<article><span class="eyebrow">${support?'BUILD AGREEMENT':'KEEP ROOM TO ACT'}</span><h3>${support?'Build a coalition':'Release contingency funds'}</h3><p>${support?'Agree on conditions with council members. This costs 3 credits and increases their support.':'Add 6 credits, at a small cost to council support. Other public priorities have to wait.'}</p>${button(support?'Negotiate support':'Reassign reserves',`cabinet:${kind}`,'secondary',disabled(G.cabinetError(state,kind)))}</article><article><span class="eyebrow">LISTEN TO RESIDENTS</span><h3>Hold a public listening session</h3><p>Improve trust and hear what people need. This uses your preparation and costs no credits.</p>${button('Hold the session','cabinet:outreach','secondary',disabled(G.cabinetError(state,'outreach')))}</article></div>${state.queue.length?`<details><summary>Investments already in progress</summary>${state.queue.map(q=>`<p>${(q.kind==='policy'?POLICIES:PROJECTS).find(p=>p.id===q.id).name}: ${Math.max(0,q.due-state.turn)} decisions remaining.</p>`).join('')}</details>`:''}<div class="modal-actions">${button('All investments','tab:policies','text-link')}${button('Back to the decision','close','primary')}</div>`,'preparation-modal');
}
function showStats(){modalShell(`<span class="eyebrow">REPUBLIC OF TALOS</span><h1>The state of the republic.</h1><div class="status-list">${Object.entries(METRICS).map(([k,m])=>`<article><strong>${m.name}<b>${Math.round(state.stats[k])}${k==='budget'?' credits':' / 100'}</b></strong><p>${m.tip}</p><div class="meter"><b style="width:${state.stats[k]}%;background:${m.color}"></b></div></article>`).join('')}</div><p class="small-note">These are fictional game indicators. They are not research estimates or forecasts.</p><div class="modal-actions">${button('Your goals','objectives','secondary')}${button('Return to the decision','close','primary')}</div>`,'status-modal');}

window.addEventListener('talos-music-change',e=>{if(state){state.settings.sound=e.detail.on;store();}for(const b of document.querySelectorAll('[data-action="sound"]'))b.textContent=e.detail.on?'♫ Sound on':'♫ Sound off';});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled)action(b.dataset.action).catch(err=>{console.error(err);toast('The action could not finish. Your last autosave is preserved.');});});
document.addEventListener('input',e=>{if(e.target.id==='score-volume'){audio.setVolume(e.target.value);$('#score-level').value=audio.volume+'%';}});
document.addEventListener('change',e=>{if(e.target.id==='sfx-enabled'){audio.sfx=e.target.checked;audio.save();}});
window.addEventListener('talos-audio-error',()=>toast('Sound could not start. Use Sound on to try again.'));
document.addEventListener('change',e=>{if(e.target.id==='overlay'){world.setOverlay(e.target.value);render();}});
$('#import-file').addEventListener('change',async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>2000000)throw Error('This file is too large to be a Talos save.');const restored=G.loadGame(await f.text());state=restored;modal=null;tab='map';selectedChoice=-1;state.settings.sound=false;audio.enable(false);prologueActive=false;store();render();toast('Saved game restored.');}catch(err){toast(err.message);}e.target.value='';});
document.addEventListener('keydown',e=>{if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;if(e.key==='Escape'){action('close');return;}if(!state||state.phase!=='playing')return;if(modalRoot.innerHTML)return;const key=e.key.toLowerCase();if(['1','2','3'].includes(key)&&!G.optionError(state,+key-1))action(`choice:${+key-1}`);const shortcuts={p:'policies',e:'evidence',c:'council',l:'journal'};if(shortcuts[key])action(`tab:${shortcuts[key]}`);});
// A modal focus loop keeps keyboard play inside the open dialog.
document.addEventListener('keydown',e=>{if(e.key!=='Tab'||!modalRoot.innerHTML)return;const els=[...modalRoot.querySelectorAll('button:not([disabled]),a,select,input,summary,video[controls]')];if(!els.length)return;const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}});
setInterval(()=>{if(state&&!document.hidden&&state.phase==='playing'){state.activeSeconds+=10;store();}},10000);
window.addEventListener('beforeunload',store);
try{world=new World($('#world'),id=>{if(!state)return;state.selected=id;world.select(id);audio.click();store();render();});}catch(e){console.error(e);$('#world').innerHTML='<div class="webgl-fallback">The 3D map needs WebGL. You can still play every decision and select districts below.</div>';$('#loading').classList.add('finished');}
// Accessible non-3D district selection is always available through this native control.
const districtSelect=document.createElement('select');districtSelect.className='district-select';districtSelect.setAttribute('aria-label','Select institution');districtSelect.innerHTML=DISTRICTS.map(d=>`<option value="${d.id}">${d.name}</option>`).join('');districtSelect.addEventListener('change',e=>{if(state){state.selected=e.target.value;store();render();}});$('#world').append(districtSelect);
window.addEventListener('talos-world-ready',()=>{document.body.classList.add('world-ready');$('#loading').classList.add('finished');if(!['film','trailer'].includes(modal)&&!prologueActive)render();});
window.Talos={getState:()=>state?G.copy(state):null,getWorldStats:()=>world?.stats(),getMusicState:()=>audio.status(),version:'6.2.0'};
render();

function chapterFilm(kind){return filmMarkup(cinematicStory(state,kind),SCENE_IMAGES,CINEMA,state.settings.reducedMotion);}
function inheritancePanel(){const film=cinematicStory(state,'era');return '<section class="inheritance"><span class="eyebrow">YOUR 2027 DECISIONS, STILL PRESENT</span>'+film.facts.map(f=>'<article><strong>'+esc(f.title)+'</strong><p>'+esc(f.text)+'</p></article>').join('')+'</section>';}
function outcomePanel(){const o=outcomeStory(state),r=DECISION_RESEARCH[o.event];return '<section class="outcome-story" data-outcome="'+o.event+'" data-route="'+o.route+'"><figure class="outcome-hero"><img src="'+SCENE_IMAGES[o.image]+'" alt="'+esc(o.alt)+'" width="1280" height="720"><figcaption><span>AFTER YOUR DECISION</span><small>AI-generated fiction</small></figcaption></figure><div class="story-aftermath"><span class="eyebrow">WHAT HAPPENS AFTER YOUR CHOICE</span><p>'+esc(o.text)+'</p></div><details class="republic-impact"><summary>See the wider impact across Talos</summary><div class="impact-scene"><img src="'+SCENE_IMAGES[o.context.image]+'" alt="'+esc(imageAlt(o.context.image))+'" width="1280" height="720"><div><span class="eyebrow">THE REPUBLIC NOW / ALL YOUR CHOICES</span><h3>'+esc(o.context.title)+'</h3><p>'+esc(o.context.text)+'</p><small>Representative fictional scene. The scores reflect all your decisions, including earlier choices and problems that continue between decisions.</small></div></div></details><details class="outcome-research"><summary>Why this matters: the research</summary><p class="lead">'+esc(r.question)+'</p><p>'+esc(r.tradeoff)+'</p>'+policyLens(o.event)+researchCards(r.sources)+'</details></section>';}
function researchCards(ids){return '<div class="research-cards">'+ids.map(id=>{const s=SOURCES.find(x=>x.id===id);return '<article><span class="eyebrow">'+esc(s.type)+' / '+esc(s.year)+'</span><h3><a href="'+s.url+'" target="_blank" rel="noopener noreferrer">'+esc(s.name)+' ↗</a></h3><p>'+esc(s.finding)+'</p><p class="source-limit"><b>What it cannot establish:</b> '+esc(s.limit)+'</p></article>';}).join('')+'</div><p class="small-note">Research helps explain the risk and the questions to ask. Events and policy effects in Talos are fictional.</p>';}

function aiPrimer(){return '<section class="ai-primer"><span class="eyebrow">UNDERSTAND THE AI</span><h2>'+AI_PRIMER.title+'</h2><p>'+AI_PRIMER.body+'</p><div class="ai-flow" aria-label="Model, connected service, human outcome"><span>Model<small>reasoning and language</small></span><b aria-hidden="true">→</b><span>Service<small>tools, memory, permissions</small></span><b aria-hidden="true">→</b><span>People<small>choices and consequences</small></span></div><p>'+AI_PRIMER.example+'</p><details><summary>What this exercise assumes</summary><p>'+AI_PRIMER.boundary+'</p><p>AI capabilities may improve, but progress also depends on computing equipment, electricity and the decisions of people and institutions. The futures in this game are possibilities, not predictions.</p>'+researchLinks(['ERA','ASTRA','OPUS55','EXTREMEEVAL'])+'</details></section>';}
function aiBriefing(later){const c=AI_CONTEXT[state.chapter],m=later?c.later:c.first,law=later?LAW_CONTEXT.later:LAW_CONTEXT.first;return '<section class="ai-briefing" data-ai-era="'+(later?'2028':'2027')+'"><span class="eyebrow">MEET THE AI / '+(later?'LATE 2028':'MID-2027')+'</span><h2>'+esc(m.name)+'</h2><p class="lead">'+esc(m.stakes)+'</p><div class="ai-brief-grid"><article><b>What it can do</b><p>'+esc(m.capability)+'</p></article><article><b>What it can access</b><p>'+esc(m.deployment)+'</p></article></div><details><summary>What the research supports and what the game assumes</summary><p>'+esc(m.unknown)+'</p>'+researchLinks(c.sources)+'</details><details class="law-context"><summary>'+esc(law.title)+'</summary><p>'+esc(law.text)+'</p><p class="small-note">'+LAW_CONTEXT.caveat+'</p>'+researchLinks(LAW_CONTEXT.sources)+'</details></section>';}
function policyLens(id){const p=POLICY_LENSES[id[0]];return '<section class="policy-lens"><span class="eyebrow">PUT THE EVIDENCE TO WORK</span><h3>'+p.title+'</h3><p>'+p.action+'</p><details><summary>Relevant European law</summary><p>'+p.law+'</p>'+researchLinks(p.sources)+'<p class="small-note">Which rules apply depends on the system, its use and the date. The game explores possible policy responses; it does not decide whether an incident would be unlawful.</p></details></section>';}
